@php($jobs = app(\App\Services\SiteRepository::class)->jobs())
<section class="career-board section-space"><div class="container-wide"><div class="section-heading reveal"><div><div class="eyebrow"><span>{{ tval($data['eyebrow']) }}</span></div><h2>{{ tval($data['title']) }}</h2></div></div>@if ($jobs->isEmpty())<p class="career-empty">{{ tval($data['empty_text']) }}</p>@else<div class="career-grid">@foreach ($jobs as $job)<article class="career-card reveal"><div class="career-meta">@if (filled($job->employment_type))<span>{{ $job->employment_type }}</span>@endif @if (filled($job->employment_type) && filled($job->location))<span>—</span>@endif @if (filled($job->location))<span>{{ $job->location }}</span>@endif</div><h2>{{ $job->title }}</h2><p>{{ $job->description }}</p><button class="button button-dark career-apply" data-job="{{ $job->id }}" type="button"><span>{{ tval($data['apply_text']) }}</span><span aria-hidden="true" class="arrow"><x-site.arrow /></span></button></article>@endforeach</div>@endif</div></section>@if ($jobs->isNotEmpty())<section class="career-application section-space" hidden="" id="applicationSection"><div class="container-wide application-layout"><div><div class="eyebrow"><span>{{ tval($data['form_eyebrow']) }}</span></div><h2>{{ tval($data['form_title']) }}</h2><p>{{ tval($data['form_intro']) }}</p></div><livewire:site.career-form :labels="$data" /></div></section>@endif
